```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    // Set up variables
    string filename, word;
    int count = 0;
    unordered_map<string, int> word_count;

    // Prompt user for input
    cout << "Enter the name of the text file: ";
    getline(cin, filename);

