    if (!file.is_open()) {
        cerr << "Error: could not open file " << filename << endl;
        return 1;
    }

    // Read file line by line
    string line;
    while (getline(file, line)) {
        // Split the line into words
        istringstream iss(line);
        string word_in_line;
        while (iss >> word_in_line) {
            // Check if the word matches the search word
            if (word_in_line == word) {
                // Increment the count if the word matches
                count++;
                // Increment the word count in the map
                word_count[word]++;
            }
        }
    }

    // Close the file
    file.close();

    // Display the results
